import React from "react";
import { Helmet } from "react-helmet";
import { useStaticQuery, graphql } from "gatsby";

const SEO = ({ 
  title, 
  description, 
  image, 
  article = false, 
  pathname,
  keywords = [] 
}) => {
  const { site } = useStaticQuery(query);

  const {
    defaultTitle,
    defaultDescription,
    siteUrl,
    defaultImage,
    social,
    keywords: defaultKeywords
  } = site.siteMetadata;

  const seo = {
    title: title || defaultTitle,
    description: description || defaultDescription,
    image: `${siteUrl}${image || defaultImage}`,
    url: `${siteUrl}${pathname || "/"}`,
    keywords: [...defaultKeywords.split(", "), ...keywords].join(", ")
  };

  return (
    <Helmet 
      title={seo.title}
      titleTemplate={title ? `%s | ${defaultTitle}` : defaultTitle}
    >
      {/* Basic Meta Tags */}
      <meta name="description" content={seo.description} />
      <meta name="keywords" content={seo.keywords} />
      <meta name="author" content="Mubashir UI Hassan" />
      <meta name="copyright" content="© 2025 Mubashir Studio. All rights reserved." />
      <meta name="robots" content="index,follow" />
      <meta name="googlebot" content="index,follow" />
      
      {/* Open Graph / Facebook */}
      <meta property="og:type" content={article ? "article" : "website"} />
      <meta property="og:title" content={seo.title} />
      <meta property="og:description" content={seo.description} />
      <meta property="og:image" content={seo.image} />
      <meta property="og:url" content={seo.url} />
      <meta property="og:site_name" content="Mubashir Studio" />
      <meta property="og:locale" content="en_US" />
      
      {/* Twitter Card */}
      <meta name="twitter:card" content="summary_large_image" />
      <meta name="twitter:title" content={seo.title} />
      <meta name="twitter:description" content={seo.description} />
      <meta name="twitter:image" content={seo.image} />
      <meta name="twitter:creator" content={social?.twitter} />
      
      {/* Additional SEO */}
      <meta name="theme-color" content="#4F46E5" />
      <meta name="msapplication-TileColor" content="#4F46E5" />
      <link rel="canonical" href={seo.url} />
      
      {/* Professional Schema Markup */}
      <script type="application/ld+json">
        {JSON.stringify({
          "@context": "https://schema.org",
          "@type": "Person",
          "name": "Mubashir UI Hassan",
          "jobTitle": "Senior UI/UX Designer & Isometric Illustration Specialist",
          "url": siteUrl,
          "image": seo.image,
          "sameAs": [
            "https://linkedin.com/in/mubashir-ui-hassan",
            "https://twitter.com/mubashirstudio",
            "https://instagram.com/mubashirstudio"
          ],
          "worksFor": {
            "@type": "Organization",
            "name": "Mubashir Studio"
          },
          "knowsAbout": [
            "UI/UX Design",
            "Isometric Illustrations", 
            "3D Design",
            "Mobile App Design",
            "Brand Identity",
            "User Experience Design",
            "Digital Design"
          ],
          "address": {
            "@type": "PostalAddress",
            "addressCountry": "Pakistan"
          }
        })}
      </script>
      
      {/* Website Schema */}
      <script type="application/ld+json">
        {JSON.stringify({
          "@context": "https://schema.org",
          "@type": "WebSite",
          "name": "Mubashir Studio",
          "url": siteUrl,
          "description": seo.description,
          "publisher": {
            "@type": "Person",
            "name": "Mubashir UI Hassan"
          }
        })}
      </script>
    </Helmet>
  );
};

export default SEO;

const query = graphql`
  query SEO {
    site {
      siteMetadata {
        defaultTitle: title
        defaultDescription: description
        siteUrl
        defaultImage: image
        keywords
        social {
          twitter
        }
      }
    }
  }
`;
